namespace Commerce.Operations.Api.Operations;
public sealed class SafeGetRetryHandler(ILogger<SafeGetRetryHandler> logger,IHttpContextAccessor contextAccessor):DelegatingHandler{protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken cancellationToken){var correlation=contextAccessor.HttpContext?.TraceIdentifier;if(!string.IsNullOrWhiteSpace(correlation))request.Headers.TryAddWithoutValidation(CorrelationMiddleware.Header,correlation);if(request.Method!=HttpMethod.Get)return await base.SendAsync(request,cancellationToken);for(var attempt=1;attempt<=3;attempt++){using var copy=Clone(request);try{var response=await base.SendAsync(copy,cancellationToken);if(attempt==3||!Transient(response.StatusCode))return response;response.Dispose();}catch(HttpRequestException exception)when(attempt<3){logger.LogWarning(exception,"Transient order engine GET failure on attempt {Attempt}",attempt);}await Task.Delay(TimeSpan.FromMilliseconds(100*Math.Pow(2,attempt-1)),cancellationToken);}throw new InvalidOperationException("Retry loop completed unexpectedly.");}private static bool Transient(System.Net.HttpStatusCode status)=>status is System.Net.HttpStatusCode.RequestTimeout or System.Net.HttpStatusCode.TooManyRequests||(int)status>=500;private static HttpRequestMessage Clone(HttpRequestMessage source){var copy=new HttpRequestMessage(source.Method,source.RequestUri);foreach(var h in source.Headers)copy.Headers.TryAddWithoutValidation(h.Key,h.Value);return copy;}}
